.btn_collapse {
  display: flex;               /* Aligns icon and text horizontally */
  align-items: center;         /* Vertically centers icon with text */
  justify-content: flex-start; /* Left-aligns content */
  width: 100%;                 /* Ensures full width for alignment */
  text-align: left;            /* Aligns text inside the button */
  padding-left: 10px;          /* Optional: adds left padding */
  white-space: normal;         /* Allows text to wrap */
}

.btn_collapse::before {
  content: "\2212";            /* Minus sign */
  margin-right: 8px;           /* Space between icon and text */
  font-size: 1.2em;            /* Optional: adjust icon size */
}

.btn.collapsed::before {
  content: "\002B";            /* Plus sign */
}



