/**Check box  radiobutton**/
.cf-checkbox, .cf-radio {
    height: 25px;
    width: 25px;
    background-color: #ffffff;
    cursor: pointer;
}

.cf-checkbox--selected{
	background-color: var(--radio_checkbox_selected);
}
.cf-checkbox--selected::before {
	content: "";
	display: block;
	position: relative;
	width: 36%;
	height: 60%;
	top: 11%;
	margin: 0 auto;
	border: 3px solid #ffffff;
	border-top-color: rgba(0, 0, 0, 0);
	border-left-color: rgba(0, 0, 0, 0);
	transform: rotate(45deg) skew(10deg);
	//background-color: var(--radio_checkbox_selected);
}
.cf-radio--selected::before
{
	    //background-color: #000000;
		background-color: var(--radio_checkbox_selected);
		transform: scale(0.7);
}
/**Other & inputs box**/
.cf-text-box {
	width: 30em;
	max-width: 100%;
	border-radius: 0px;
	border: none;
	border-bottom: 1px solid #ffffff;
	background-color: #ffffff;
	font-size: inherit;
	text-overflow: ellipsis;
	padding: 0 .5em;
	padding-top: 1px;
	line-height: 2em;
	height: 2em;
}
.cf-navigation__button {
	width: 5%;
	min-width: 118px;
	max-width: 184px;
	min-height: 1.5em
}
