if (IsInRdgMode())
{
    f('QPOSTCODE').set('0810 WAGAMAN, NT');
}
else
{
const qn_location = "QPOSTCODE";
const qn_state = "s_state";
const qn_finalPcode = "finalPostcode";
const qn_pcodeList = "pcode_list"
// Clears all location-related fields
function clearLocationFields() {
    const locationFields = [
        "finalPostcode",
        "finalSuburb",
        "finalState",
        "finalLGA_pcprim",
        "finalLGA_locprim",
        "finalCombined",
        "finalMarket",
        "finalMarket_name",
        "finalRemoteness",
        "finalSEIFA_irsd"
    ];
    locationFields.forEach(field => f(field).set(""));
}

// error message for invalid postcode
var errmsg;
function setError() {
    clearLocationFields();
    RaiseError();
    ClearErrorMessage();
    ClearQuestionErrorMessage();
    SetQuestionErrorMessage(LangIDs.en_au, errmsg);
}

function validatePcode(pcode, state, array) {
    var postcode = String(pcode).padStart(4, '0');
    var getStates = [...new Set(array.map(([_, state]) => state))];
    var getPcodes = [...new Set(array.map(([pcode, _]) => pcode))];
    if (getStates.includes(state)) {
        if(array.some(([pc, st]) => pc === postcode && st === state)) {
            return postcode;
        } else {
            errmsg = "Please enter a postcode within " + state + ".";
        }   
    } else {
        if (getPcodes.includes(postcode)) {
            return postcode
        } else {
            errmsg = "Please enter a valid postcode to proceed.";
        }
    }
    return null;
}

// if not DK/REF, validate postcode
const noResponseValue = f(qn_location).getNoResponseValue();
if (noResponseValue == null) { // validate entry
    const locationResponse = f(qn_location).toString().slice(0,4);
    if (Number(locationResponse) > 0) {
        f(qn_finalPcode).set(validatePcode(locationResponse, f(qn_state).get(), JSON.parse(f(qn_pcodeList))));
    }
    if (f(qn_finalPcode).toBoolean()) {
        if (!locationResponse.includes(f(qn_finalPcode).get())) {
            setError();
        }
    } else { // finalpcode is empty - no match
        if (!isNaN(locationResponse)) {
            setError();
        }
    }
} else {
    clearLocationFields();
}
}

