Info.StartupScript:
const qn_location = "QPOSTCODE";
const qn_state = "s_state";
const mapping = {
  pcode: "finalPostcode",
  locality: "finalSuburb",
  state: "finalState",
  lga_pcprim: "finalLGA_pcprim",
  lga_locprim: "finalLGA_locprim",
  combined: "finalCombined",
  primary_src_market: "finalMarket",
  primary_src_market_name: "finalMarket_name",
  primary_remoteness: "finalRemoteness",
  seifa_irsd_2021: "finalSEIFA_irsd"
};
// this is used to validate pcode if droplist not selected - see custom validation in Location node
const qn_pcodeList = "pcode_list"
/* ------------------------------------------------------------------------------------------------ */

/* if state is needed for a response to filter, comment below to show */
document.getElementById(qn_state).setAttribute("style", "display:none");

/* hide fields from user view */
for (const key in mapping) {
  if (document.getElementById(mapping[key]) !== null) {
    document.getElementById(mapping[key]).setAttribute("style", "display:none");
  }
}
function autocomplete(inp, arr) {
  let currentFocus;
  inp.addEventListener("input", function(e) {
    let val = this.value;
    closeAllLists();
    if (!val) { return false;}
    currentFocus = -1;
    const listContainer = createListContainer(this);
    var filterArr = filterState(arr, Confirmit.page.getQuestion(qn_state).value);
    populateList(filterArr, val, listContainer);
  });
  //option for using arrow keys to select
  inp.addEventListener("keydown", function(e) {
    let x = document.getElementById(this.id + "autocomplete-list");
    if (x) x = x.getElementsByTagName("div");
    if (e.keyCode == 40) {
      currentFocus++;
      addActive(x);
    } else if (e.keyCode == 38) {
      currentFocus--;
      addActive(x);
    } else if (e.keyCode == 13) {
      e.preventDefault();
      if (currentFocus > -1) {
        if (x) x[currentFocus].click();
      }
    }
  });
  function addActive(x) {
    if (!x) return false;
    removeActive(x);
    if (currentFocus >= x.length) currentFocus = 0;
    if (currentFocus < 0) currentFocus = (x.length - 1);
    x[currentFocus].classList.add("autocomplete-active");
    const activeItems = document.getElementsByClassName("autocomplete-active");
    for (let i = 0; i < activeItems.length; i++) {
      activeItems[i].style.backgroundColor = "#eee";
    }
  }
  function removeActive(x) {
    for (let i = 0; i < x.length; i++) {
      x[i].classList.remove("autocomplete-active");
      x[i].style.backgroundColor = "#fff";
    }
  }
  //create dropdown
  function createListContainer(inputElement) {
    const container = document.createElement("DIV");
    container.setAttribute("id", inputElement.id + "autocomplete-list");
    container.setAttribute("class", "autocomplete-items");
    container.setAttribute("style", "position: absolute; border: 1px solid #d4d4d4; border-bottom: none; border-top: none; z-index: 99; background-color: #fff; overflow-y: auto; box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);");
    inputElement.after(container);
    return container;
  }
  //check and insert matched items to dropdown
  /*function populateList(arr, val, container) {
    let listCount = 0;
    for (let i = 0; i < arr.length && listCount < 8; i++) {
      //use this if variable is an array, currently an object
      //if (arr[i][0].toUpperCase().includes(val.toUpperCase()) || arr[i][1].toUpperCase().includes(val.toUpperCase())) {
      if (arr[i].pcode.toUpperCase().startsWith(val) || arr[i].pcode.toUpperCase().startsWith("0" + val) ||
         (val.length<4  && arr[i].locality.toUpperCase().startsWith(val.toUpperCase()) ||
          val.length>=4 && arr[i].locality.toUpperCase().includes(val.toUpperCase()))
        ) {
        const item = createListItem(arr[i], val);
        container.appendChild(item);
        listCount++;
      }
    }
  }*/
function populateList(arr, val, container) {
  const normalizedVal = val.toUpperCase();
  const matches = [];

  // Pass 1: startsWith matches
  for (let i = 0; i < arr.length && matches.length < 8; i++) {
    const pcode = String(arr[i].pcode);
    const locality = arr[i].locality.toUpperCase();

    if (pcode.startsWith(val) || pcode.startsWith("0" + val) || locality.startsWith(normalizedVal)) {
      matches.push(arr[i]);
    }
  }

  // Pass 2: includes matches (only if needed)
  if (matches.length < 8) {
    for (let i = 0; i < arr.length && matches.length < 8; i++) {
      const locality = arr[i].locality.toUpperCase();
      if (!locality.startsWith(normalizedVal) && locality.includes(normalizedVal)) {
        matches.push(arr[i]);
      }
    }
  }

  // Render top 8
  matches.forEach(item => {
    container.appendChild(createListItem(item, val));
  });
}
  //create item to add to dropdown
  function createListItem(data, val) {
    const item = document.createElement("DIV");
    item.setAttribute("style", "padding: 10px; cursor: pointer; background-color: #fff; border-bottom: 1px solid #d4d4d4;");
    //use this if variable is an array, currently an object
    //const displayText = `${data[0]} ${data[1].toUpperCase()}, ${data[2]}`.toUpperCase();
    const displayText = `${data.pcode} ${data.locality.toUpperCase()}, ${data.state}`.toUpperCase();
    item.innerHTML = highlightMatch(displayText, val);
    //use this if variable is an array, currently an object
    //item.innerHTML += `<input type='hidden' class='selection' name='${data[0]}-${data[1]}-${data[2]}' value='${displayText}' data-pcode='${data[0]}' data-suburb='${data[1]}' data-state='${data[2]}'>`;
    item.innerHTML += `<input type='hidden' class='selection' name='${data.combined}' value='${displayText}' data-pcode='${data.pcode}' data-locality='${data.locality}' data-state='${data.state}' data-lga_pcprim='${data.lga_pcprim}' data-lga_locprim='${data.lga_locprim}' data-combined='${data.combined}' data-primary_src_market='${data.primary_src_market}' data-primary_src_market_name='${data.primary_src_market_name}' data-primary_remoteness='${data.primary_remoteness}' data-seifa_irsd_2021='${data.seifa_irsd_2021}'>`;
    item.addEventListener('mouseover', () => {item.style.backgroundColor = '#eee';});
    item.addEventListener('mouseout', () => {item.style.backgroundColor = '#fff';});
    item.addEventListener("click", function (e) {
      setQuestionValue(qn_location, this.getElementsByTagName("input")[0].value);
      //see mapping to set all field names
      //setQuestionValue("FinalPostcode", this.getElementsByTagName("input")[0].dataset.pcode);
      const inputElement = this.getElementsByTagName("input")[0];
      for (const key in mapping) {
        if (document.getElementById(mapping[key]) !== null) {
          setQuestionValue(mapping[key], inputElement.dataset[key]);
        }
      }
      closeAllLists();
    });
    return item;
  }
  //bold matching substring in dropdown
  function highlightMatch(text, val) {
    const index = text.indexOf(val.toUpperCase());
    if (index === -1) {
      return text;
    } else if (index === 0) {
      return `<strong>${text.substring(0, val.length)}</strong>${text.substring(val.length)}`;
    } else {
      return `${text.substring(0, index)}<strong>${text.substring(index, index + val.length)}</strong>${text.substring(index + val.length)}`;
    }
  }
  function closeAllLists(elmnt) {
    let x = document.getElementsByClassName("autocomplete-items");
    for (let i = 0; i < x.length; i++) {
      if (elmnt != x[i] && elmnt != inp) {
        x[i].parentNode.removeChild(x[i]);
      }
    }
  }
  //check state has value filter if true
  function filterState(arr, state) {
    if (arr.filter(item => item.state === state).length > 0) {

      return arr.filter(item => item.state === state);
    } else {
      return arr;
    }
  }
  //use this to assign values to variables, using JavaScript doesn't work
  function setQuestionValue(qId, val) {
    Confirmit.page.getQuestion(qId).setValue(val);
  }
  //hide dropdown on mouseclick
  document.addEventListener("click", function (e) {
    closeAllLists(e.target);
  });
}
