var K6_score = 0
var codes = f('BP_2x1').domainValues()

// Define score mapping for response codes
var scoreMap = {
    '1': 5,
    '2': 4,
    '3': 3,
    '4': 2,
    '5': 1
};

//Loop through all iterations of BP_2x1
for (var i = 0; i < codes.length; i++) {
    var code = codes[i];
    var item = f('BP_2x1').item(code);

    // Check which response was selected and add corresponding score
    for (var response in scoreMap) {
        if (item.any(response)) {
            K6_score += scoreMap[response];
            break; // Stop checking once a match is found
        }
    }
}

