Open.ValidationCode:
var qid = CurrentForm();
var mno  = "";
var flg = false;

//Extract new no.
if (f(qid).toBoolean()) {
    mno = f(qid).get();
}

//validate new no.
if (mno.charAt(0) == "0" && mno.length == 10 && IsNumeric(mno)) {
    flg = true;
}

if (!flg && f(qid).toBoolean()) {
    errormessage('9');
